PROGRAM ST040_ACKBUFFERT
VAR
    steg        : INT := 0;
    antal       : INT := 0;
    trigIn      : R_TRIG;
    trigUt      : F_TRIG;
    tmrStill    : TON;
    xVantar     : BOOL := FALSE;
    xFull       : BOOL := FALSE;
    xViktfel    : BOOL := FALSE;
    xDriftsklar : BOOL := FALSE;
END_VAR

(* EMG_OK lases bara. Logiken bar ingen sakerhetsfunktion; den ar forreglad AV
   nodstoppskretsen. *)

(* Rakningen sker pa FLANKER, aldrig pa nivaer. En lastbarare pa 600 mm haller
   inloppsfotocellens stralen bruten i 600/400 = 1,5 s, alltsa 75 scan; raknas
   nivan okas raknaren en gang per scan och bufferten tror sig full langt innan
   den ar det. Utgangen raknas ner pa FALLANDE flank, alltsa nar lastbararen
   verkligen lamnat utloppet. *)
trigIn(CLK := ST040_PEC_IN);
trigUt(CLK := ST040_PEC_OUT);

IF trigIn.Q THEN
    antal := antal + 1;
END_IF;
IF trigUt.Q AND antal > 0 THEN
    antal := antal - 1;
END_IF;
ST040_BUF_COUNT := antal;

(* Vikten och rakningen ska ga ihop. En tom KLT 6147 vager drygt 1,5 kg och en
   fylld 9,5 kg, sa under 4,0 kg per raknad lastbarare kan bara en av dem ha
   ratt. Da far ingen lastbarare slappas ut pa en rakning styrningen inte kan
   lita pa. Raknaren nollstalls INTE: den ar bokforing, inte ett don. *)
xViktfel := (antal >= 1) AND (ST040_WGT_LOAD < (4.0 * INT_TO_REAL(antal)));

(* Hysteresen 12/11 ar stationens egen: full vid 12 platser om 600 mm, alltsa
   12*600 = 7200 mm buffert, och inflodet slapps in igen forst nar antalet
   fallit till 11. Lastgransen 130 kg ar hardare an platsrakningen. *)
IF (antal >= 12) OR (ST040_WGT_LOAD > 130.0) THEN
    xFull := TRUE;
ELSIF antal <= 11 THEN
    xFull := FALSE;
END_IF;
ST040_BUF_FULL := xFull;

xDriftsklar := EMG_OK AND NOT xViktfel;
ST040_STP_IN_OPEN := xDriftsklar AND NOT xFull;

(* Lastbararen ska sta stilla 0,60 s innan utloppsgrinden oppnar, langre an
   rullbanans efterslapning vid 24 m/min = 0,4 m/s. *)
xVantar := (steg = 1);
tmrStill(IN := xVantar, PT := T#600ms);

IF NOT xDriftsklar THEN
    ST040_STP_OUT_OPEN := FALSE;
    ST040_DEM_ACK := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST040_STP_OUT_OPEN := FALSE;
            IF ST040_DEM_REQ AND ST040_PEC_OUT AND (antal > 0) THEN
                steg := 1;
            END_IF;
        1:
            IF tmrStill.Q THEN
                ST040_STP_OUT_OPEN := TRUE;
                steg := 2;
            END_IF;
        2:
            IF trigUt.Q THEN
                ST040_STP_OUT_OPEN := FALSE;
                ST040_DEM_ACK := TRUE;
                steg := 3;
            END_IF;
        3:
            IF NOT ST040_DEM_REQ THEN
                ST040_DEM_ACK := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

